using var vf = SKTypeface.FromFile("NotoSans[wght].ttf");
var wght = SKFourByteTag.Parse("wght");

SKTypeface CloneAt(float w) =>
    vf.Clone([ new SKFontVariationPositionCoordinate { Axis = wght, Value = w } ]);

float ShapedWidth(SKTypeface tf)
{
    using var shaper = new SKShaper(tf);
    using var font = new SKFont(tf, 80);
    return shaper.Shape("Weight", font).Width;
}

using var thin  = CloneAt(100);
using var black = CloneAt(900);

// Both return same value (~266.1) — bug:
Console.WriteLine($"{ShapedWidth(thin)} vs {ShapedWidth(black)}");

// SKFont correctly differs (~247.3 vs ~300.4):
using var f100 = new SKFont(thin, 80);
using var f900 = new SKFont(black, 80);
Console.WriteLine($"{f100.MeasureText("Weight")} vs {f900.MeasureText("Weight")}");

