var coords = Typeface.VariationDesignPosition;
if (coords.Length > 0)
{
    var variations = new HarfBuzzSharp.Variation[coords.Length];
    for (var i = 0; i < coords.Length; i++)
        variations[i] = new HarfBuzzSharp.Variation { Tag = coords[i].Axis, Value = coords[i].Value };
    hbFont.SetVariations(variations);
}
